def f(n, d=0):
    if n == 1:
        return d
    return f(n // 2, d + 1) if n % 2 == 0 else f(3 * n + 1, d + 1)
m = {k: f(k) for k in range(6, 12)}
best = max(m, key=lambda k: (m[k], -k))
print(best * 100 + m[best])
